// @DanuZz
#!/usr/bin/env node
const { generateWelcomeCard, parseArgs } = require('../src/welcome');
const { instadl } = require('../src/instagram');
const { fetchNews, getSiteList, categories } = require('../src/news'); // Updated: Add getSiteList and categories at top
const { ytmp3, ytmp4, search } = require('../src/youtube');
const { pinterest } = require('../src/pinterest');
const mova = require('../src/mova');
const fs = require('fs');
const path = require('path');
const readline = require('readline');
const { stdin: input, stdout: output } = require('process');
// Simple CLI handler with subcommands
const args = process.argv.slice(2);
const subcommand = args[0];
if (subcommand === '--help' || args.length === 0) {
  const helpText = `
Usage: movanest <subcommand> [options]
Subcommands:
  welcome Generate a welcome card image (default if no subcommand)
    --background <url> Background image URL (default: random minimalistic)
    --avatar <url> Avatar image URL (default: random minimalistic)
    --text1 <text> Primary text (default: "MovaNest")
    --text2 <text> Secondary text (default: "Welcome To Mova Community")
    --text3 <text> Tertiary text (default: "@DanuZz")
    --text4 <text> Optional text 4
    --text5 <text> Optional text 5
    --width <px> Canvas width (default: 800)
    --height <px> Canvas height (default: 400)
    --output <file> Output PNG file (default: welcome.png)
  instadl <url> Download Instagram media info
    <url> Instagram post URL (e.g., https://www.instagram.com/p/ABC123/)
    --output <dir> Optional: Directory to save media (default: current dir)
  news [category|site1,site2...] Fetch top news from sites/categories
    If category provided: Interactively select sites from list.
    If sites provided: Direct fetch (comma-separated).
    --num-sites <N> Limit to N sites (default: 5, ignored in interactive mode)
    --format <text|json> Output format (default: text)
    --output <file> Save to file (JSON only)
    --non-interactive Force direct fetch even for category (use with --num-sites)
  ytmp3 <url> Get YouTube audio download info
    <url> YouTube video URL
    --quality <kbps> Audio quality (default: 128, options: 32,64,96,128,160,192,256,320)
    --format <text|json> Output format (default: text)
  ytmp4 <url> Get YouTube video download info
    <url> YouTube video URL
    --quality <p> Video quality (default: 360, options: 144,240,360,480,720,1080,1440)
    --format <text|json> Output format (default: text)
  search <query> Search YouTube videos
    <query> Search terms
    --limit <n> Number of results (default: 10)
    --format <text|json> Output format (default: text)
  pinterest <query> Search Pinterest pins
    <query> Search terms
    --page-size <n> Number of results (default: 25)
    --format <text|json> Output format (default: text)
    --output <file> Save to file (JSON only)
  mova [<text>|art <keyword>|file <path>] Enhanced colored console output
    <text> Print the provided text (supports multi-word)
    art <keyword> Print matching ASCII art (e.g., cat, rocket)
    file <path> Print content from file
    # If no arguments after 'mova', reads from pipe (stdin)
    --color <name|hex> Text color (default: cyan, e.g., red, #ff0000)
    --rainbow Rainbow colors (overrides --color)
    --animate Animate the output
    --duration <n> Animation frames (default: 12)
    --speed <n> Animation speed ms/frame (default: 20)
Examples:
  movanest news international # Interactive: Select sites
  movanest news bbc,cnn # Direct fetch
  movanest news tech --format json --output news.json
  movanest news international --non-interactive --num-sites 3
  movanest ytmp3 https://youtube.com/watch?v=ABC123 --quality 192
  movanest ytmp4 https://youtube.com/watch?v=ABC123 --quality 720 --format json
  movanest search "funny cats" --limit 5
  movanest pinterest "funny cats" --page-size 10
  movanest pinterest "cute puppies" --format json --output pins.json
  movanest mova "Hello World" --color green --animate
  movanest mova art cat --color yellow
  movanest mova file log.txt --rainbow
  echo "Piped text" | movanest mova
  movanest mova art rocket --rainbow --animate
  movanest --help
  `;
  mova.fromString(helpText, { color: 'yellow' });
  process.exit(0);
}
// Helper: Interactive prompt using readline
function prompt(question) {
  const rl = readline.createInterface({ input, output });
  return new Promise(resolve => rl.question(question, ans => {
    rl.close();
    resolve(ans.trim());
  }));
}
// Helper: Parse comma-separated numbers for selection
function parseSelection(input, maxIndex) {
  if (!input) return [];
  return input.split(',').map(s => s.trim()).filter(Boolean)
    .map(num => parseInt(num) - 1) // 1-based to 0-based
    .filter(idx => idx >= 0 && idx < maxIndex)
    .map(idx => idx + 1); // Back to 1-based for display, but use 0-based for array
}
// Helper: Handle output (text or JSON)
function handleOutput(result, format = 'text', outputFile = null) {
  let output = result;
  if (format === 'json') {
    output = typeof result === 'string' ? result : JSON.stringify(result, null, 2);
    if (outputFile) {
      fs.writeFileSync(path.resolve(outputFile), output);
      mova.println(`${format.toUpperCase()} saved: ${path.resolve(outputFile)}`, { color: 'green' });
      return;
    }
  }
  mova.fromString(output.toString(), { color: 'cyan' });
}
// Handle welcome card (default or explicit)
if (subcommand === 'welcome' || !subcommand || subcommand.startsWith('--')) {
  // Shift args if subcommand is 'welcome' to treat as options
  if (subcommand === 'welcome') {
    args.shift();
  }
  const options = parseArgs({ argv: args });
  generateWelcomeCard(options)
    .then(buffer => {
      fs.writeFileSync(options.output, buffer);
      mova.println(`Welcome card generated: ${path.resolve(options.output)}`, { color: 'green' });
    })
    .catch(err => {
      mova.println(`Error generating welcome card: ${err.message}`, { color: 'red' });
      process.exit(1);
    });
}
// Handle Instagram download
else if (subcommand === 'instadl') {
  const url = args[1];
  if (!url) {
    mova.println('Error: Instagram URL is required. Use: movanest instadl <url>', { color: 'red' });
    process.exit(1);
  }
  const outputDir = args.find(arg => arg.startsWith('--output='))?.split('=')[1] || args.find(arg => arg === '--output') ? args[args.indexOf('--output') + 1] : process.cwd();
  instadl(url)
    .then(result => {
      if (result.status) {
        mova.println('Instagram Media Download Info:', { color: 'blue' });
        mova.println(`Type: ${result.type}`, { color: 'cyan' });
        if (result.type === 'video') {
          mova.println(`Video URL: ${result.videoUrl}`, { color: 'cyan' });
          mova.println(`Poster: ${result.posterUrl}`, { color: 'cyan' });
        } else {
          mova.println(`Image URL: ${result.imageUrl}`, { color: 'cyan' });
        }
        mova.println(`Download URL: ${result.downloadUrl}`, { color: 'green' });
        if (outputDir && outputDir !== process.cwd()) {
          mova.println(`\\nSaving to: ${path.resolve(outputDir)}`, { color: 'yellow' });
          mova.println(' (Extend CLI to auto-download if desired)', { color: 'gray' });
        }
      } else {
        mova.println(`Error: ${result.message}`, { color: 'red' });
        process.exit(1);
      }
    })
    .catch(err => {
      mova.println(`Unexpected error: ${err.message}`, { color: 'red' });
      process.exit(1);
    });
}
// Handle YouTube MP3 (audio)
else if (subcommand === 'ytmp3') {
  const url = args[1];
  if (!url) {
    mova.println('Error: YouTube URL is required. Use: movanest ytmp3 <url>', { color: 'red' });
    process.exit(1);
  }
  const qualityArg = args.find(arg => arg.startsWith('--quality='));
  const quality = qualityArg ? parseInt(qualityArg.split('=')[1]) : 128;
  const formatArg = args.find(arg => arg.startsWith('--format='));
  const format = formatArg ? formatArg.split('=')[1] : 'text';
  const outputArg = args.find(arg => arg.startsWith('--output='));
  const outputFile = outputArg ? outputArg.split('=')[1] : null;
  ytmp3(url, quality)
    .then(result => {
      if (result.status) {
        mova.println('YouTube Audio Download Info:', { color: 'blue' });
        mova.println(`Title: ${result.metadata.title}`, { color: 'cyan' });
        mova.println(`Author: ${result.metadata.author.name}`, { color: 'cyan' });
        mova.println(`Duration: ${result.metadata.timestamp}`, { color: 'cyan' });
        mova.println(`Download URL: ${result.download.url}`, { color: 'green' });
        mova.println(`Quality: ${result.download.quality}`, { color: 'cyan' });
        if (result.download.size) mova.println(`Size: ${result.download.size} bytes`, { color: 'cyan' });
        mova.println(`Filename: ${result.download.filename}`, { color: 'cyan' });
      } else {
        mova.println(`Error: ${result.message}`, { color: 'red' });
        process.exit(1);
      }
      handleOutput(result, format, outputFile);
    })
    .catch(err => {
      mova.println(`Unexpected error: ${err.message}`, { color: 'red' });
      process.exit(1);
    });
}
// Handle YouTube MP4 (video)
else if (subcommand === 'ytmp4') {
  const url = args[1];
  if (!url) {
    mova.println('Error: YouTube URL is required. Use: movanest ytmp4 <url>', { color: 'red' });
    process.exit(1);
  }
  const qualityArg = args.find(arg => arg.startsWith('--quality='));
  const quality = qualityArg ? parseInt(qualityArg.split('=')[1]) : 360;
  const formatArg = args.find(arg => arg.startsWith('--format='));
  const format = formatArg ? formatArg.split('=')[1] : 'text';
  const outputArg = args.find(arg => arg.startsWith('--output='));
  const outputFile = outputArg ? outputArg.split('=')[1] : null;
  ytmp4(url, quality)
    .then(result => {
      if (result.status) {
        mova.println('YouTube Video Download Info:', { color: 'blue' });
        mova.println(`Title: ${result.metadata.title}`, { color: 'cyan' });
        mova.println(`Author: ${result.metadata.author.name}`, { color: 'cyan' });
        mova.println(`Duration: ${result.metadata.timestamp}`, { color: 'cyan' });
        mova.println(`Download URL: ${result.download.url}`, { color: 'green' });
        mova.println(`Quality: ${result.download.quality}`, { color: 'cyan' });
        if (result.download.size) mova.println(`Size: ${result.download.size} bytes`, { color: 'cyan' });
        mova.println(`Filename: ${result.download.filename}`, { color: 'cyan' });
      } else {
        mova.println(`Error: ${result.message}`, { color: 'red' });
        process.exit(1);
      }
      handleOutput(result, format, outputFile);
    })
    .catch(err => {
      mova.println(`Unexpected error: ${err.message}`, { color: 'red' });
      process.exit(1);
    });
}
// Handle YouTube search
else if (subcommand === 'search') {
  const query = args[1];
  if (!query) {
    mova.println('Error: Search query is required. Use: movanest search <query>', { color: 'red' });
    process.exit(1);
  }
  const limitArg = args.find(arg => arg.startsWith('--limit='));
  const limit = limitArg ? parseInt(limitArg.split('=')[1]) : 10;
  const formatArg = args.find(arg => arg.startsWith('--format='));
  const format = formatArg ? formatArg.split('=')[1] : 'text';
  const outputArg = args.find(arg => arg.startsWith('--output='));
  const outputFile = outputArg ? outputArg.split('=')[1] : null;
  search(query)
    .then(result => {
      if (result.status) {
        mova.println(`YouTube Search Results for "${query}" (${limit} results):`, { color: 'blue' });
        result.results.slice(0, limit).forEach((video, idx) => {
          mova.println(`${idx + 1}. ${video.title} by ${video.author.name} (${video.timestamp})`, { color: 'cyan' });
          mova.println(` URL: ${video.url}`, { color: 'green' });
          mova.println(` Thumbnail: ${video.thumbnail}`, { color: 'gray' });
          mova.println('', { color: 'reset' }); // Empty line
        });
      } else {
        mova.println(`Error: ${result.message}`, { color: 'red' });
        process.exit(1);
      }
      handleOutput({ query, results: result.results.slice(0, limit) }, format, outputFile);
    })
    .catch(err => {
      mova.println(`Unexpected error: ${err.message}`, { color: 'red' });
      process.exit(1);
    });
}
// Handle Pinterest search
else if (subcommand === 'pinterest') {
  const query = args[1];
  if (!query) {
    mova.println('Error: Search query is required. Use: movanest pinterest <query>', { color: 'red' });
    process.exit(1);
  }
  const pageSizeArg = args.find(arg => arg.startsWith('--page-size='));
  const pageSize = pageSizeArg ? parseInt(pageSizeArg.split('=')[1]) : 25;
  const formatArg = args.find(arg => arg.startsWith('--format='));
  const format = formatArg ? formatArg.split('=')[1] : 'text';
  const outputArg = args.find(arg => arg.startsWith('--output='));
  const outputFile = outputArg ? outputArg.split('=')[1] : null;
  pinterest(query, { pageSize, format })
    .then(result => {
      // Detect error: for json, check status; for text, check if it's a JSON error string
      let isError = false;
      let errorMsg = '';
      if (format === 'json') {
        isError = !result.status;
        if (isError) errorMsg = result.error;
      } else {
        // For text, error is JSON stringified
        try {
          const parsed = JSON.parse(result);
          isError = !parsed.status;
          if (isError) errorMsg = parsed.error;
        } catch {
          // Not JSON, assume success (formatted text)
        }
      }
      if (isError) {
        mova.println(`Error: ${errorMsg}`, { color: 'red' });
        process.exit(1);
      }
      handleOutput(result, format, outputFile);
    })
    .catch(err => {
      mova.println(`Unexpected error: ${err.message}`, { color: 'red' });
      process.exit(1);
    });
}
// Handle Mova enhanced print
else if (subcommand === 'mova') {
  mova.init();
  // Parse positional and options
  let positional = [];
  let optMap = {};
  for (let i = 1; i < args.length; i++) {
    let arg = args[i];
    if (arg.startsWith('--')) {
      let eqIndex = arg.indexOf('=');
      let key = arg.slice(2, eqIndex > -1 ? eqIndex : undefined);
      let val = eqIndex > -1 ? arg.slice(eqIndex + 1) : true;
      optMap[key] = val;
    } else {
      positional.push(arg);
    }
  }
  let color = optMap.color || mova.options.defaultColor;
  let isRainbow = optMap.rainbow;
  if (isRainbow) color = 'rainbow';
  let isAnimate = optMap.animate;
  if (optMap.duration) mova.options.duration = parseInt(optMap.duration) || 12;
  if (optMap.speed) mova.options.speed = parseInt(optMap.speed) || 20;
  let opts = { color, animate: isAnimate };
  let action = positional[0];
  if (action === 'art') {
    let keyword = positional[1];
    if (!keyword) {
      mova.println('Error: Keyword required for art.', { color: 'red' });
      process.exit(1);
    }
    mova.printArt(keyword, color);
  } else if (action === 'file') {
    let filePath = positional[1];
    if (!filePath) {
      mova.println('Error: File path required.', { color: 'red' });
      process.exit(1);
    }
    try {
      let content = fs.readFileSync(path.resolve(filePath), 'utf8');
      mova.fromString(content, opts);
    } catch (err) {
      mova.println(`Error reading file: ${err.message}`, { color: 'red' });
      process.exit(1);
    }
  } else if (positional.length === 0) {
    // Pipe from stdin
    process.stdin.resume();
    process.stdin.setEncoding('utf8');
    let data = '';
    process.stdin.on('data', (chunk) => {
      data += chunk;
    });
    process.stdin.on('end', () => {
      let lines = data.split('\n').filter(l => l.trim());
      lines.forEach((line) => {
        mova.options.seed += 1;
        mova.println(line, opts);
      });
      process.exit(0);
    });
  } else {
    // Text mode
    let text = positional.join(' ');
    if (!text.trim()) {
      mova.println('Error: No text provided.', { color: 'red' });
      process.exit(1);
    }
    mova.fromString(text, opts);
  }
}
// Updated: Handle News fetch with interactivity
else if (subcommand === 'news') {
  const categoryOrSites = args[1];
  if (!categoryOrSites) {
    mova.println('Error: Category or sites required. Use: movanest news <category|site1,site2...>', { color: 'red' });
    process.exit(1);
  }
  const numSitesArg = args.find(arg => arg.startsWith('--num-sites='));
  const numSites = numSitesArg ? parseInt(numSitesArg.split('=')[1]) : 5;
  const formatArg = args.find(arg => arg.startsWith('--format='));
  const format = formatArg ? formatArg.split('=')[1] : 'text';
  const outputArg = args.find(arg => arg.startsWith('--output='));
  const outputFile = outputArg ? outputArg.split('=')[1] : null;
  const nonInteractiveArg = args.includes('--non-interactive');
  // If direct sites provided (comma-separated, not a category)
  if (!categories.includes(categoryOrSites)) {
    const siteList = categoryOrSites.split(',').map(s => s.trim()).filter(Boolean);
    const options = { sites: siteList, numSites, format };
    fetchNews(options)
      .then(result => handleOutput(result, format, outputFile))
      .catch(err => {
        mova.println(`Error fetching news: ${err.message}`, { color: 'red' });
        process.exit(1);
      });
    return;
  }
  // Category mode
  if (nonInteractiveArg) {
    // Non-interactive: fetch top N directly
    const options = { category: categoryOrSites, numSites, format };
    fetchNews(options)
      .then(result => handleOutput(result, format, outputFile))
      .catch(err => {
        mova.println(`Error fetching news: ${err.message}`, { color: 'red' });
        process.exit(1);
      });
    return;
  }
  // Interactive mode for category
  (async () => {
    try {
      mova.println(`\\nCategory: ${categoryOrSites}`, { color: 'blue' });
      const siteList = getSiteList(categoryOrSites);
      mova.println('Available sites:', { color: 'yellow' });
      siteList.forEach((site, idx) => {
        mova.println(`${idx + 1}. ${site.name} (${site.key})`, { color: 'cyan' });
      });
      const selectionInput = await prompt(`\\nSelect sites by numbers (comma-separated, e.g., 1,3,5) or 'all' for all, or 'top5' for first 5: `);
 
      let selectedKeys;
      if (selectionInput.toLowerCase() === 'all') {
        selectedKeys = siteList.map(s => s.key);
      } else if (selectionInput.toLowerCase() === 'top5') {
        selectedKeys = siteList.slice(0, 5).map(s => s.key);
      } else {
        const indices = parseSelection(selectionInput, siteList.length);
        if (indices.length === 0) {
          mova.println('No valid selections. Exiting.', { color: 'red' });
          process.exit(1);
        }
        selectedKeys = indices.map(i => siteList[i - 1].key); // 1-based
      }
      mova.println(`\\nFetching from: ${selectedKeys.join(', ')}`, { color: 'green' });
      mova.println('', { color: 'reset' });
 
      // Call fetchNews with sites
      const formatted = await fetchNews({ sites: selectedKeys, format });
      handleOutput(formatted, format, outputFile);
    } catch (err) {
      mova.println(`Error in interactive mode: ${err.message}`, { color: 'red' });
      process.exit(1);
    }
  })();
}
// Unknown subcommand
else {
  mova.println(`Unknown subcommand: ${subcommand}. Run 'movanest --help' for usage.`, { color: 'red' });
  process.exit(1);
}
